begin;
set local lock_timeout='5s';
create table zoi.property_offers(id uuid primary key,workspace_id uuid not null references zoi.workspaces(id),host_id uuid not null references zoi.listings(id),place_id uuid references zoi.listings(id),data jsonb not null,status text not null,published boolean not null default false,source_conflict boolean not null default false,conflict_reason text not null default '',version integer not null default 1,initial_data jsonb not null,created_by uuid not null references zoi.user_profiles(id),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp());
create index property_offer_workspace on zoi.property_offers(workspace_id,updated_at desc);
create index property_offer_host on zoi.property_offers(host_id,published);
create table zoi.property_audit(id bigint generated always as identity primary key,offer_id uuid not null references zoi.property_offers(id),workspace_id uuid not null references zoi.workspaces(id),actor_id uuid not null references zoi.user_profiles(id),before_state jsonb,after_state jsonb not null,created_at timestamptz not null default clock_timestamp());
create index property_audit_workspace on zoi.property_audit(workspace_id,id desc);
create table zoi.property_requests(id uuid primary key default gen_random_uuid(),offer_id uuid not null references zoi.property_offers(id),profile_id uuid not null references zoi.user_profiles(id),request_id uuid not null,initial_data jsonb not null,data jsonb not null,offer_snapshot jsonb not null,inquiry_id uuid not null unique references zoi.inquiry_threads(id),created_at timestamptz not null default clock_timestamp(),unique(profile_id,request_id));
create index property_request_profile on zoi.property_requests(profile_id,created_at desc);
alter table zoi.property_offers enable row level security;alter table zoi.property_audit enable row level security;alter table zoi.property_requests enable row level security;
revoke all on zoi.property_offers,zoi.property_audit,zoi.property_requests from public,anon,authenticated;
create function zoi.property_actor(p_workspace uuid) returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid;begin if auth.uid() is null or coalesce(zoi.ops_role(p_workspace),'') not in('owner','admin') then raise exception 'property_permission_denied' using errcode='42501';end if;select id into actor from zoi.user_profiles where auth_user_id=auth.uid();return actor;end $$;
create function zoi.property_current(p zoi.property_offers) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from zoi.listings l where l.id=p.host_id and l.owner_workspace_id=p.workspace_id and l.publish_status='published' and coalesce(l.marketplace_status,'')<>'hidden') and (p.place_id is null or exists(select 1 from zoi.listings l where l.id=p.place_id and l.owner_workspace_id=p.workspace_id and l.publish_status='published' and coalesce(l.marketplace_status,'')<>'hidden'))$$;
create function zoi.property_facts(p jsonb) returns jsonb language plpgsql stable set search_path='' as $$declare mode text;price bigint;area numeric;bedrooms integer;reviewed date;source text;photos jsonb;begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>40000 then raise exception 'invalid_property';end if;mode:=p->>'mode';source:=coalesce(p->>'source_url','');photos:=coalesce(p->'photos','[]');
 if coalesce(mode,'') not in('sale','long_rent','holiday_stay') or not exists(select 1 from pg_catalog.pg_timezone_names where name=p->>'timezone') or length(btrim(coalesce(p->>'title',''))) not between 1 and 180 or length(coalesce(p->>'description',''))>5000 or length(btrim(coalesce(p->>'city',''))) not between 1 and 120 or length(btrim(coalesce(p->>'country',''))) not between 1 and 120 or length(coalesce(p->>'public_address',''))>300 or coalesce(p->>'currency','') !~ '^[A-Z]{3}$' or jsonb_typeof(p->'price_on_request') is distinct from 'boolean' or length(coalesce(p->>'fee_terms',''))>2000 or coalesce(p->>'representation','') not in('owner','authorized_agent') or jsonb_typeof(p->'representation_confirmed') is distinct from 'boolean' then raise exception 'invalid_property';end if;
 begin price:=(p->>'price_cents')::bigint;area:=(p->>'area')::numeric;bedrooms:=(p->>'bedrooms')::integer;exception when others then raise exception 'invalid_property_measurements';end;
 if ((p->>'price_on_request')::boolean and price is not null) or (not (p->>'price_on_request')::boolean and (price is null or price<0 or price>100000000000000)) or (area is not null and (area<=0 or area>100000000 or coalesce(p->>'area_unit','') not in('sqm','sqft'))) or (area is null and nullif(p->>'area_unit','') is not null) or (bedrooms is not null and bedrooms not between 0 and 100) then raise exception 'invalid_property_measurements';end if;
 if source<>'' and (length(source)>2000 or source !~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]+)?(/[^[:space:]<>]*)?$') then raise exception 'invalid_property_source';end if;
 if nullif(p->>'source_checked_on','') is not null then if p->>'source_checked_on' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'invalid_property_source';end if;reviewed:=(p->>'source_checked_on')::date;if reviewed>current_date then raise exception 'invalid_property_source';end if;end if;
 if jsonb_typeof(photos)<>'array' then raise exception 'invalid_property_photos';end if;if jsonb_array_length(photos)>12 or exists(select 1 from jsonb_array_elements(photos) x where jsonb_typeof(x)<>'string' or length(x#>>'{}')>2000 or (x#>>'{}') !~ '^https://[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]+)?/[^[:space:]<>]*$') then raise exception 'invalid_property_photos';end if;
 return jsonb_build_object('mode',mode,'timezone',p->>'timezone','price_basis',case mode when 'sale' then 'asking_price' when 'long_rent' then 'monthly' else 'nightly' end,'title',btrim(p->>'title'),'description',coalesce(p->>'description',''),'city',btrim(p->>'city'),'country',btrim(p->>'country'),'public_address',coalesce(p->>'public_address',''),'price_on_request',(p->>'price_on_request')::boolean,'price_cents',price,'currency',p->>'currency','area',area,'area_unit',nullif(p->>'area_unit',''),'bedrooms',bedrooms,'photos',photos,'fee_terms',coalesce(p->>'fee_terms',''),'source_url',source,'source_checked_on',reviewed,'representation',p->>'representation','representation_confirmed',(p->>'representation_confirmed')::boolean);
end $$;
revoke all on function zoi.property_actor(uuid),zoi.property_current(zoi.property_offers),zoi.property_facts(jsonb) from public,anon,authenticated;
create function public.property_offer_save(p_workspace uuid,p_id uuid,p_expected_version integer,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid;p zoi.property_offers;prior zoi.property_offers;facts jsonb;host uuid;place uuid;conflict boolean;pub boolean;v_status text;begin
 actor:=zoi.property_actor(p_workspace);perform 1 from zoi.workspaces where id=p_workspace for update;select * into prior from zoi.property_offers where id=p_id for update;
 if prior.id is not null and prior.workspace_id is distinct from p_workspace then raise exception 'property_permission_denied';end if;
 if p_expected_version=0 and prior.id is not null then if prior.initial_data is distinct from p_data then raise exception 'property_request_conflict';end if;return jsonb_build_object('ok',true,'offer',to_jsonb(prior));end if;
 if p_id is null or jsonb_typeof(p_data->'published') is distinct from 'boolean' or jsonb_typeof(p_data->'source_conflict') is distinct from 'boolean' or length(coalesce(p_data->>'conflict_reason',''))>2000 then raise exception 'invalid_property';end if;
 facts:=zoi.property_facts(p_data);host:=(p_data->>'host_id')::uuid;place:=nullif(p_data->>'place_id','')::uuid;conflict:=(p_data->>'source_conflict')::boolean;pub:=(p_data->>'published')::boolean and not conflict;v_status:=p_data->>'status';
 if coalesce(v_status,'') not in('available','under_offer','sold','let','unavailable') or (v_status='sold' and facts->>'mode'<>'sale') or (v_status='let' and facts->>'mode'='sale') or (conflict and btrim(coalesce(p_data->>'conflict_reason',''))='') then raise exception 'invalid_property_status';end if;
 if pub and (facts->>'source_url'='' or facts->>'source_checked_on' is null or (facts->>'representation_confirmed')::boolean is distinct from true or btrim(facts->>'fee_terms')='') then raise exception 'property_publication_facts_required';end if;
 perform 1 from zoi.listings where id in(host,place) order by id for share;
 if not exists(select 1 from zoi.listings where id=host and owner_workspace_id=p_workspace and publish_status='published' and coalesce(marketplace_status,'')<>'hidden' and entity_type in('professional','business','travel_place','venue','organization')) or (place is not null and not exists(select 1 from zoi.listings where id=place and owner_workspace_id=p_workspace and publish_status='published' and coalesce(marketplace_status,'')<>'hidden' and entity_type in('business','travel_place','venue'))) then raise exception 'property_home_unavailable';end if;
 if prior.id is null then if p_expected_version is distinct from 0 then raise exception 'property_version_conflict';end if;if (select count(*) from zoi.property_offers where workspace_id=p_workspace)>=200 then raise exception 'property_offer_limit';end if;
 insert into zoi.property_offers(id,workspace_id,host_id,place_id,data,status,published,source_conflict,conflict_reason,initial_data,created_by) values(p_id,p_workspace,host,place,facts,v_status,pub,conflict,coalesce(p_data->>'conflict_reason',''),p_data,actor) returning * into p;
 else if prior.version is distinct from p_expected_version then raise exception 'property_version_conflict';end if;if exists(select 1 from zoi.property_requests where offer_id=p_id) and (prior.host_id is distinct from host or prior.place_id is distinct from place or prior.data->>'mode' is distinct from facts->>'mode') then raise exception 'property_identity_locked';end if;
 update zoi.property_offers set host_id=host,place_id=place,data=facts,status=v_status,published=pub,source_conflict=conflict,conflict_reason=coalesce(p_data->>'conflict_reason',''),version=version+1,updated_at=clock_timestamp() where id=p_id returning * into p;end if;
 insert into zoi.property_audit(offer_id,workspace_id,actor_id,before_state,after_state) values(p.id,p_workspace,actor,case when prior.id is null then null else to_jsonb(prior) end,to_jsonb(p));return jsonb_build_object('ok',true,'offer',to_jsonb(p));end $$;
create function public.property_operator(p_workspace uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid;owned jsonb;offers jsonb;audit jsonb;requests jsonb;begin actor:=zoi.property_actor(p_workspace);
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'entity_type',entity_type) order by name),'[]') into owned from zoi.listings where owner_workspace_id=p_workspace and publish_status='published' and coalesce(marketplace_status,'')<>'hidden' and entity_type in('professional','business','travel_place','venue','organization');
 select coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc),'[]') into offers from zoi.property_offers p where p.workspace_id=p_workspace;
 select coalesce(jsonb_agg(to_jsonb(q)),'[]') into audit from(select * from zoi.property_audit where workspace_id=p_workspace order by id desc limit 100)q;select coalesce(jsonb_agg(to_jsonb(q)),'[]') into requests from(select r.* from zoi.property_requests r join zoi.property_offers p on p.id=r.offer_id where p.workspace_id=p_workspace order by r.created_at desc,r.id limit 100)q;return jsonb_build_object('ok',true,'owned',owned,'offers',offers,'audit',audit,'requests',requests);end $$;
create function public.property_catalog(p_host uuid default null,p_offer uuid default null,p_mode text default null,p_city text default '') returns jsonb language plpgsql stable security definer set search_path='' as $$declare offers jsonb;begin
 if length(coalesce(p_city,''))>120 or (p_mode is not null and p_mode not in('sale','long_rent','holiday_stay')) then raise exception 'invalid_property_filter';end if;
 select coalesce(jsonb_agg(to_jsonb(q)),'[]') into offers from(select p.id,p.host_id,p.place_id,p.version,p.data,p.status,p.updated_at,l.name agent_name,l.slug agent_slug,place.name place_name,place.slug place_slug,case when exists(select 1 from zoi.booking_settings b where b.listing_id=l.id and b.workspace_id=l.owner_workspace_id and b.enabled) then '/book/?listing='||l.id end booking_url,'/properties/?offer='||p.id offer_url from zoi.property_offers p join zoi.listings l on l.id=p.host_id left join zoi.listings place on place.id=p.place_id where p.published and not p.source_conflict and zoi.property_current(p) and (p_host is null or p.host_id=p_host) and (p_offer is null or p.id=p_offer) and (p_mode is null or p.data->>'mode'=p_mode) and (coalesce(p_city,'')='' or position(lower(p_city) in lower(p.data->>'city'))>0) order by p.updated_at desc,p.id limit 50)q;return jsonb_build_object('ok',true,'offers',offers);end $$;
create function public.property_request(p_offer uuid,p_expected_version integer,p_request uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid;p zoi.property_offers;r zoi.property_requests;t zoi.inquiry_threads;v_start timestamptz;v_end timestamptz;data jsonb;body text;begin
 if auth.uid() is null then raise exception 'sign_in_required';end if;actor:=zoi.ensure_profile();perform 1 from zoi.user_profiles where id=actor for update;
 select * into r from zoi.property_requests where profile_id=actor and request_id=p_request;if r.id is not null then if r.offer_id is distinct from p_offer or r.initial_data is distinct from p_data or (r.offer_snapshot->>'version')::integer is distinct from p_expected_version then raise exception 'property_request_conflict';end if;return jsonb_build_object('ok',true,'request',to_jsonb(r));end if;
 if p_request is null or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>20000 or coalesce(p_data->>'kind','') not in('information','viewing','stay') or length(btrim(coalesce(p_data->>'message',''))) not between 1 and 3000 then raise exception 'invalid_property_request';end if;
 select * into p from zoi.property_offers where id=p_offer for share;if p.id is null or not p.published or p.source_conflict or p.status<>'available' or not zoi.property_current(p) then raise exception 'property_unavailable';end if;if p.version is distinct from p_expected_version then raise exception 'property_offer_changed';end if;
 if p_data->>'kind'='stay' and p.data->>'mode'<>'holiday_stay' then raise exception 'property_stay_request_invalid';end if;
 if p_data->>'kind'<>'information' then
  if p_data->>'timezone' is distinct from p.data->>'timezone' or coalesce(p_data->>'preferred_start','') !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' or coalesce(p_data->>'preferred_end','') !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_data->>'timezone') then raise exception 'property_timezone_required';end if;
  begin v_start:=(p_data->>'preferred_start')::timestamptz;v_end:=(p_data->>'preferred_end')::timestamptz;exception when others then raise exception 'invalid_property_dates';end;if not isfinite(v_start) or not isfinite(v_end) or v_start<clock_timestamp()-interval '1 minute' or v_end<=v_start or v_end-v_start>interval '90 days' then raise exception 'invalid_property_dates';end if;
 end if;
 if (select count(*) from zoi.property_requests where profile_id=actor and created_at>clock_timestamp()-interval '1 day')>=10 then raise exception 'property_request_limit';end if;
 data:=jsonb_build_object('kind',p_data->>'kind','message',btrim(p_data->>'message'),'preferred_start',v_start,'preferred_end',v_end,'timezone',case when v_start is not null then p_data->>'timezone' end);
 body:='Property: '||(p.data->>'title')||E'\nRequest: '||(p_data->>'kind')||case when v_start is null then '' else E'\nPreferred: '||v_start::text||' to '||v_end::text||' ('||(p_data->>'timezone')||')' end||E'\n'||btrim(p_data->>'message')||E'\nThis is a request, not a confirmed appointment, stay or purchase.';
 insert into zoi.inquiry_threads(listing_id,workspace_id,customer_id,request_id,subject,initial_body) values(p.host_id,p.workspace_id,actor,gen_random_uuid(),'Property: '||left(p.data->>'title',100),body) returning * into t;
 insert into zoi.inquiry_messages(thread_id,author_id,author_side,request_id,body) values(t.id,actor,'customer',gen_random_uuid(),body);insert into zoi.inquiry_audit(thread_id,actor_id,action,after_state) values(t.id,actor,'created',jsonb_build_object('status','open','version',1,'source','property_request'));
 insert into zoi.property_requests(offer_id,profile_id,request_id,initial_data,data,offer_snapshot,inquiry_id) values(p.id,actor,p_request,p_data,data,jsonb_build_object('id',p.id,'version',p.version,'host_id',p.host_id,'place_id',p.place_id,'data',p.data,'status',p.status),t.id) returning * into r;return jsonb_build_object('ok',true,'request',to_jsonb(r));end $$;
create function public.property_requests_mine() returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid;rows jsonb;begin if auth.uid() is null then raise exception 'sign_in_required';end if;select id into actor from zoi.user_profiles where auth_user_id=auth.uid();select coalesce(jsonb_agg(to_jsonb(q)),'[]') into rows from(select * from zoi.property_requests where profile_id=actor order by created_at desc,id limit 50)q;return jsonb_build_object('ok',true,'requests',rows);end $$;
revoke all on function public.property_offer_save(uuid,uuid,integer,jsonb),public.property_operator(uuid),public.property_catalog(uuid,uuid,text,text),public.property_request(uuid,integer,uuid,jsonb),public.property_requests_mine() from public,anon,authenticated;
grant execute on function public.property_catalog(uuid,uuid,text,text) to anon,authenticated;
grant execute on function public.property_offer_save(uuid,uuid,integer,jsonb),public.property_operator(uuid),public.property_request(uuid,integer,uuid,jsonb),public.property_requests_mine() to authenticated;
commit;
